  read_plot(find_panel(d3b, c(
    "panelC_recovery_classes_lowspikes_Fnuc",
    "panelB_recovery_classes_lowspikes_Fnuc"
  ))),
  nrow = 1,
  rel_widths = c(1.85, 1),
