  ))),
  read_plot(find_panel(d4, "panel_B_biomarker_outcome_vs_intuitive_drivers_with_trends_naturestyle")),
  read_plot(find_panel(d4, "panel_C_intuitive_association_dot_summary_naturestyle")),
  ncol = 1, rel_heights = c(1, 1.1, 0.7)
)
save(fig4, "Fig4_biomarker_recoverability", 12.2, 18.2)

fig5 <- plot_grid(
  read_plot(find_panel(d5a, "panel_A_independent_vs_community_good_recovery_dumbbell")),
  read_plot(find_panel(d5a, "panel_B_community_good_recovery_dumbbell_main_effective_fractions")),
  read_plot(find_panel(d5b, "panel_B_community_target_DA_detection_main_effective_fractions")),
  ncol = 1, rel_heights = c(1, 1, 1.05)
)
save(fig5, "Fig5_community_spike_recovery_and_DA", 13.5, 18.6)

writeLines(c(
  "Current manuscript figure mapping",
  "Figure 1: study-design schematic in manuscript source (no statistical analysis)",
  "Figure 2: baseline profiler discordance",
  "Supplementary Figure B2: baseline profiler discordance for all 10 targets",
  "Figure 3: independent spike recovery",
  "Figure 4: biomarker recoverability",
  "Figure 5: community spike recovery and differential abundance",
  "Figures 6 and 7: generated by dedicated scripts in the main runner"
), file.path(outdir, "FIGURE_MAPPING.txt"))
